specimens.css:
/* 静态快照 + 布局补位：真实卡片宽由会话列的 --dsh-chat-content-width 决定（示例里该变量不存在，max-width 失效），这里用固定宽度还原一屏。 */
.root { padding-inline: 16px; }
/* 悬停模拟：:hover 无法静态触发，下面这条按 ApprovalPanel.module.css 的同名规则原样搬运。 */
.reject.forceHover:not(:disabled) { background: var(--dsw-alias-interactive-bg-hover-danger); color: var(--dsw-alias-state-error-primary); border-color: transparent; }
